/* ================= 12 色主题 ================= */
function applyThemeByGlobalIndex(index){
  state.themeIdx = index;
  var themeObj = allThemes[index];
  if (!themeObj) return;
  var root = document.documentElement;
  root.style.setProperty("--orb-color-1", themeObj.orb1);
  root.style.setProperty("--orb-color-2", themeObj.orb2);
  root.style.setProperty("--refresh-btn-bg", themeObj.refreshBg);
  root.style.setProperty("--send-circle-bg", themeObj.sendCircleBg);
  root.style.setProperty("--theme-accent", themeObj.accent);
  root.style.setProperty("--theme-tag-bg", themeObj.tagBg);
  root.style.setProperty("--theme-tag-text", themeObj.tagText);
  root.style.setProperty("--search-glow", themeObj.glow);
  if (themeObj.isHolo) root.setAttribute("data-holo", "true");
  else root.removeAttribute("data-holo");
  if (!state.dark) root.style.setProperty("--page-bg", themeObj.pageBg);
  var orbLeft = document.getElementById("orbLeft");
  var orbRight = document.getElementById("orbRight");
  if (!themeObj.isHolo) {
    var shift = index % 2 === 0 ? 1 : -1;
    orbLeft.style.transform = "translate(" + (shift * 12) + "px, " + (-shift * 6) + "px) scale(" + (1 + shift * 0.04) + ")";
    orbRight.style.transform = "translate(" + (-shift * 12) + "px, " + (shift * 6) + "px) scale(" + (1 - shift * 0.04) + ")";
  } else {
    orbLeft.style.transform = "";
    orbRight.style.transform = "";
  }
  updateSwatchActiveState();
}
function renderThemeSwatches(){
  var grid = document.getElementById("themeSwatchGrid");
  grid.innerHTML = allThemes.map(function(t, idx){
    var label = zh() ? t.name : t.nameEn;
    var isActive = idx === state.themeIdx ? " active" : "";
    var holoClass = t.isHolo ? " holo-animated" : "";
    return '<div class="theme-swatch-item' + isActive + '" data-theme-idx="' + idx + '">' +
      '<span class="swatch-orb-preview' + holoClass + '" style="background: linear-gradient(135deg, ' + t.orb1 + ' 0%, ' + t.orb2 + ' 65%, ' + t.refreshBg + ' 100%);"></span>' +
      '<span class="swatch-label">' + esc(label) + "</span></div>";
  }).join("");
  grid.querySelectorAll(".theme-swatch-item").forEach(function(el){
    el.addEventListener("click", function(){ selectThemeFromPanel(Number(el.getAttribute("data-theme-idx"))); });
  });
}
function updateSwatchActiveState(){
  document.querySelectorAll(".theme-swatch-item").forEach(function(el){
    el.classList.toggle("active", Number(el.getAttribute("data-theme-idx")) === state.themeIdx);
  });
}
function openThemePanel(){
  document.getElementById("themePopover").classList.add("open");
  document.getElementById("themeBackdrop").classList.add("open");
  if (navigator.vibrate) navigator.vibrate(18);
}
function closeThemePanel(){
  document.getElementById("themePopover").classList.remove("open");
  document.getElementById("themeBackdrop").classList.remove("open");
  document.querySelectorAll(".theme-swatch-item").forEach(function(el){ el.classList.remove("sliding-hover"); });
}
function selectThemeFromPanel(idx){
  applyThemeByGlobalIndex(idx);
  savePrefs();
  closeThemePanel();
  var t = allThemes[idx];
  showToast(zh() ? "已切换主题：" + t.name : "Theme applied: " + t.nameEn);
}
document.getElementById("themeBackdrop").addEventListener("click", closeThemePanel);

