/* ================= 标签筛选（按真实分类生成） ================= */
function buildTagChips(){
  var bar = document.getElementById("subtagFilterBar");
  var cats = ALL_CATS.slice();
  var tags = ["all"].concat(cats).concat(["Free", "Freemium", "Paid"]);
  bar.innerHTML = tags.map(function(t){
    var label = t === "all" ? (zh() ? "全部标签" : "All Tags") : t;
    return '<button type="button" class="subtag-chip' + (state.tag === t ? " active" : "") + '" data-tag="' + esc(t) + '">' + esc(label) + "</button>";
  }).join("");
  bar.querySelectorAll(".subtag-chip").forEach(function(chip){
    chip.addEventListener("click", function(){
      state.tag = chip.getAttribute("data-tag");
      bar.querySelectorAll(".subtag-chip").forEach(function(c){ c.classList.toggle("active", c === chip); });
      renderAll();
    });
  });
}

/* ================= 条目渲染 ================= */
function matches(it){
  if (state.tag !== "all") {
    if (state.tag === "Free" && it.pricing !== "free") return false;
    if (state.tag === "Freemium" && it.pricing !== "freemium") return false;
    if (state.tag === "Paid" && it.pricing !== "paid") return false;
    if (state.tag !== "Free" && state.tag !== "Freemium" && state.tag !== "Paid" && it.cat !== state.tag) return false;
  }
  if (!state.q) return true;
  var hay = (it.name + " " + (it.tagline || "") + " " + (it.descZh || "") + " " + (it.cat || "") + " " + (it.host || "")).toLowerCase();
  return hay.indexOf(state.q) !== -1;
}
function cardHtml(it){
  var desc = zh() ? (it.descZh || it.tagline) : it.tagline;
  if (desc) desc = desc.replace(/\u3002$/, "");
  var chips = "";
  if (it.cat) chips += '<span class="designeer-badge">' + esc(it.cat) + "</span>";
  var pl = pricingLabel(it.pricing);
  if (pl) chips += '<span class="designeer-badge' + (it.pricing === "freemium" ? " pricing-freemium" : it.pricing === "paid" ? " pricing-paid" : "") + '">' + pl + "</span>";
  return '<a class="catalogue-card" href="' + esc(it.url) + '" target="_blank" rel="noopener">' +
    "<div>" +
      '<div class="card-header-line"><span class="card-title-text"><span>' + esc(it.name) + '</span><span class="card-arrow-icon">↗</span></span>' +
      (it.host ? '<span class="card-domain-hint">' + esc(it.host) + "</span>" : "") + "</div>" +
      '<p class="card-desc-text">' + esc(desc) + "</p>" +
    "</div>" +
    '<div class="card-tags-row">' + chips + "</div></a>";
}
function renderCollection(key){
  if (!CATALOG[key]) { var g0 = document.querySelector('[data-grid="' + key + '"]'); if (g0) g0.innerHTML = ""; var b0 = document.querySelector('[data-more="' + key + '"]'); if (b0) b0.style.display = "none"; var s0 = document.getElementById(key); if (s0) s0.querySelector("[data-empty]").style.display = "none"; return; }
  var grid = document.querySelector('[data-grid="' + key + '"]');
  var items = CATALOG[key].filter(matches);
  var showAll = state.expanded[key] || !!state.q || state.tag !== "all";
  var shown = showAll ? items : items.slice(0, PAGE);
  grid.innerHTML = shown.map(cardHtml).join("");
  var btn = document.querySelector('[data-more="' + key + '"]');
  if (!showAll && items.length > PAGE) {
    btn.style.display = "";
    btn.textContent = zh() ? "显示全部 " + items.length + " 条" : "Show all " + items.length + " entries";
  } else { btn.style.display = "none"; }
  var sec = document.getElementById(key);
  sec.querySelector("[data-empty]").style.display = items.length ? "none" : "block";
}
function renderFinds(){
  if (!FINDS) { document.getElementById("findsGrid").innerHTML = ""; document.getElementById("finds").querySelector("[data-empty]").style.display = "none"; return; }
  var grid = document.getElementById("findsGrid");
  var items = FINDS.filter(function(f){
    if (state.tag !== "all") return false;
    if (!state.q) return true;
    return (f.name + " " + (f.handle || "")).toLowerCase().indexOf(state.q) !== -1;
  });
  grid.innerHTML = items.map(function(f){
    var ratio = (f.w && f.h) ? ' style="aspect-ratio:' + f.w + "/" + f.h + '"' : "";
    return '<article class="find-poster-card">' +
      '<img class="poster-img" data-src="' + esc(f.local) + '" alt="Find by ' + esc(f.name) + '"' + ratio + ">" +
      '<div class="poster-author-bar"><span class="poster-author-name">' + esc(f.name) + "</span>" +
      (f.handle ? '<span class="poster-author-handle">@' + esc(f.handle) + "</span>" : "") + "</div></article>";
  }).join("");
  bindPosterLazy(grid);
  document.getElementById("finds").querySelector("[data-empty]").style.display = items.length ? "none" : "block";
}
function renderAll(){
  COLLECTIONS.forEach(renderCollection);
  renderFinds();
  var note = document.getElementById("searchNote");
  if (state.q) {
    var n = 0;
    COLLECTIONS.forEach(function(k){ n += (CATALOG[k] || []).filter(matches).length; });
    note.style.display = "block";
    note.textContent = zh() ? "共 " + n + " 条目录条目匹配「" + state.q + "」" : n + " catalogue entries match \u201C" + state.q + "\u201D";
  } else { note.style.display = "none"; }
}
document.querySelectorAll("[data-more]").forEach(function(btn){
  btn.addEventListener("click", function(){
    state.expanded[btn.getAttribute("data-more")] = true;
    renderCollection(btn.getAttribute("data-more"));
  });
});

